import{_ as i,l as n,o as e,c as r,v as t,p as s,x as l,d as c,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"CPS 与延续","description":"","frontmatter":{"title":"CPS 与延续","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cps-continuations.md","filePath":"cs/cps-continuations.md","lastUpdated":1789023840000}'),h={name:"cs/cps-continuations.md"};function C(S,a,u,P,_,m){const o=n("Mermaid");return e(),r("div",null,[a[1]||(a[1]=t('<h1 id="cps-与延续" tabindex="-1">CPS 与延续 <a class="header-anchor" href="#cps-与延续" aria-label="Permalink to &quot;CPS 与延续&quot;">​</a></h1><div class="epigraph"><p>把「剩下要做的事」当成函数参数。CPS 变换后每个调用都是尾调用，控制流变成跳转；call/cc 把当前延续物化。</p><footer>—— 据 Steele, RABBIT；Appel, Compiling with Continuations；Plotkin, Call-by-name, Call-by-value and the λ-Calculus 整理</footer></div><p>上一课<a href="/cs/closure-conversion">闭包转换</a> 处理环境。缺口是<strong>控制</strong>：return、异常、协程都是延续的使用。CPS：<code>f(x)</code> 变 <code>f(x, k)</code>，\\(k\\) 是「接受结果的函数」。本课钉变换直觉与为何利于<a href="/cs/tail-call-opt">尾调用</a>。协程下一课。不重写 STLC。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>直接风格：调用栈隐式延续。CPS：显式。编译器（SML/NJ、早期编译器）用 CPS 作 IR：优化是函数传递。缺口是<strong>这一 IR</strong>，不是闭包字段布局。</p><p>call/cc：把当前 \\(k\\) 当成值。实现要能复制或分享栈——重。</p><h3 id="延续不是「回调-hell-的散文」" tabindex="-1">延续不是「回调 hell 的散文」 <a class="header-anchor" href="#延续不是「回调-hell-的散文」" aria-label="Permalink to &quot;延续不是「回调 hell 的散文」&quot;">​</a></h3><p>JS 回调是粗糙 CPS。完整 call/cc 可多次调用 \\(k\\)（若允许），语义更强。不要等同。</p><p><span class="marginnote">Steele RABBIT。Appel CWC。Plotkin 1975。本课编译用途为主。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对核心 λ 做 CPS 变换（有多种，注意行政性归约）。然后闭包转换、分配。优化：已知 \\(k\\) 则跳转。异常：把 handler 编进 \\(k\\)。</p>',11)),(e(),s(d,null,{default:l(()=>[p(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20DS%5B%22%E7%9B%B4%E6%8E%A5%E9%A3%8E%E6%A0%BC%22%5D%20--%3E%20CPS%5B%22%E6%98%BE%E5%BC%8F%E5%BB%B6%E7%BB%AD%22%5D%0A%20%20CPS%20--%3E%20TC%5B%22%E5%85%A8%E6%98%AF%E5%B0%BE%E8%B0%83%E7%94%A8%22%5D%0A%20%20TC%20--%3E%20JMP%5B%22%E8%B7%B3%E8%BD%AC%20%2F%20%E9%97%AD%E5%8C%85%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与操作语义：求值上下文就是延续的语法形式。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>栈：CPS 后若不当尾调用优化会爆栈——必须 TCO。管理性闭包多，要好分配/逃逸。不要把每次 <code>+</code> 都真的堆分配 \\(k\\) 而不优化。</p><p>与 JIT：CPS IR 少见，但 SSA 也是「剩余计算」的亲戚（Appel 论文）。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写协程实现。后课默认：控制可 CPS 化。下一课协程与生成器：一次延续、可暂停。</p><p>也不把 CPS 当密码学。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CPS：其余计算当函数参数；调用变尾调用。</li><li>编译器 IR 或 call/cc 的基础。</li><li>必须配合 TCO 与闭包优化。</li><li>出处：Steele；Appel CWC；Plotkin。</li></ul>',9))])}const A=i(h,[["render",C]]);export{E as __pageData,A as default};
